def forward(apps, schema_editor):
    """Set the preferred distributions for all languages.

    This is normally the same as the German except for some geodienste layers which have additional
    distribution for some languages.
    """
    Dataset = apps.get_model("dataset", "Dataset")
    ExternalWMSDistribution = apps.get_model("distribution", "ExternalWMSDistribution")
    for dataset in Dataset.objects.all().iterator():
        if not dataset.preferred_distribution_de:
            continue

        supported_languages = set(dataset.preferred_distribution_de.supported_languages)
        for lang in supported_languages:
            setattr(dataset, f"preferred_distribution_{lang}", dataset.preferred_distribution_de)

        for lang in {"fr", "en", "it", "rm"} - supported_languages:
            distribution = ExternalWMSDistribution.objects.filter(
                dataset=dataset, meta_information=False, supported_languages__contains=[lang]
            ).first()
            setattr(dataset, f"preferred_distribution_{lang}", distribution)

        dataset.save(
            update_fields=[
                "preferred_distribution_fr",
                "preferred_distribution_en",
                "preferred_distribution_it",
                "preferred_distribution_rm",
            ]
        )


